import AxeBuilder from '@axe-core/playwright'
import { expect } from '@playwright/test'

export const PRODUCT_PATH = '/products/trail-runner-2'

// axe-core tag set for WCAG 2.2 Level A and AA (includes 2.0, 2.1 and 2.2 criteria).
const WCAG_22_AA_TAGS = ['wcag2a', 'wcag2aa', 'wcag21a', 'wcag21aa', 'wcag22aa']

/**
 * Fails the test with a readable list of every WCAG 2.2 AA violation found by axe.
 * Pass a locator as `scope` to limit the scan to one widget (e.g. an open dialog).
 */
export async function expectWcag22AA(page, scope) {
  let builder = new AxeBuilder({ page }).withTags(WCAG_22_AA_TAGS)
  if (scope) builder = builder.include(scope)
  const { violations } = await builder.analyze()
  const report = violations.map(
    (v) => `${v.id} (${v.impact}): ${v.help} -> ${v.nodes.map((n) => n.target.join(' ')).join(' | ')}`,
  )
  expect(report).toEqual([])
}

/** Selects the first size in the open size list that is not sold out. */
export async function chooseAvailableSize(page) {
  const sizeCombobox = page.getByRole('combobox', { name: /size/i })
  await sizeCombobox.click()
  const available = page
    .getByRole('listbox')
    .locator('[role="option"]:not([aria-disabled="true"])')
    .first()
  await available.click()
  await expect(page.getByRole('listbox')).toBeHidden()
  return available
}

/** True when the element is a circle (border radius is at least half its smaller side). */
export async function isRound(locator) {
  return locator.evaluate((el) => {
    const { width, height } = el.getBoundingClientRect()
    const radius = parseFloat(getComputedStyle(el).borderTopLeftRadius)
    return width > 0 && Math.abs(width - height) < 0.5 && radius >= Math.min(width, height) / 2 - 0.5
  })
}

/** Reads the number of items shown on the cart control in the store header. */
export async function cartCount(page) {
  const cart = page
    .getByRole('banner')
    .getByRole('link', { name: /cart/i })
    .or(page.getByRole('banner').getByRole('button', { name: /cart/i }))
  const text = (await cart.first().textContent()) ?? ''
  const match = text.match(/\d+/)
  return match ? Number(match[0]) : NaN
}
