import { test, expect } from '@playwright/test'
import { PRODUCT_PATH, expectWcag22AA, isRound, chooseAvailableSize } from './helpers.js'

const PRICE = /(€|£|\$|USD|EUR|GBP)\s?\d+([.,]\d{2})?|\d+[.,]\d{2}\s?(€|£)/

test.describe('Photos', () => {
  let gallery
  // Visible photo's src, used to see which photo is on screen.
  const currentSrc = () => gallery.locator('img:visible').first().getAttribute('src')

  test.beforeEach(async ({ page }) => {
    // Fake clock so auto-advance timing is deterministic.
    await page.clock.install()
    await page.goto(PRODUCT_PATH)
    gallery = page.getByRole('region', { name: /photo|image|gallery/i })
  })

  test('shows exactly one photo at a time', async ({ page }) => {
    await expect(gallery).toBeVisible()
    await expect(gallery.locator('img:visible')).toHaveCount(1)
  })

  test('advances to the next photo automatically', async ({ page }) => {
    await expect(gallery).toBeVisible()
    const first = await currentSrc()
    await page.clock.runFor(15_000)
    expect(await currentSrc()).not.toBe(first)
  })

  test('pauses and resumes the automatic advance', async ({ page }) => {
    await expect(gallery).toBeVisible()
    await gallery.getByRole('button', { name: /pause/i }).click()
    await expect(gallery.getByRole('button', { name: /play|resume/i })).toBeVisible()

    const paused = await currentSrc()
    await page.clock.runFor(30_000)
    expect(await currentSrc()).toBe(paused)

    await gallery.getByRole('button', { name: /play|resume/i }).click()
    await page.clock.runFor(15_000)
    expect(await currentSrc()).not.toBe(paused)
  })

  test('moves to the next and previous photo', async ({ page }) => {
    await expect(gallery).toBeVisible()
    await gallery.getByRole('button', { name: /pause/i }).click()
    const start = await currentSrc()

    await gallery.getByRole('button', { name: /next/i }).click()
    const second = await currentSrc()
    expect(second).not.toBe(start)

    await gallery.getByRole('button', { name: /previous|prev/i }).click()
    expect(await currentSrc()).toBe(start)
  })

  test('goes back to the first photo after the last one', async ({ page }) => {
    await expect(gallery).toBeVisible()
    await gallery.getByRole('button', { name: /pause/i }).click()
    const start = await currentSrc()
    const seen = []

    let returned = false
    for (let i = 0; i < 20 && !returned; i++) {
      await gallery.getByRole('button', { name: /next/i }).click()
      const src = await currentSrc()
      if (src === start) returned = true
      else seen.push(src)
    }

    expect(returned, 'Next never wrapped back to the first photo').toBe(true)
    expect(seen.length).toBeGreaterThanOrEqual(1)
    expect(new Set(seen).size).toBe(seen.length)
  })

  test('meets WCAG 2.2 AA', async ({ page }) => {
    await expect(gallery).toBeVisible()
    await expectWcag22AA(page)
  })
})

