test.describe('Keyboard and focus (WCAG 2.4.3, 2.4.7, 2.4.11)', () => {
  test('every tab stop shows a visible focus indicator and is not hidden behind other content', async ({ page }) => {
    await page.goto(PRODUCT_PATH)
    await expect(page.getByRole('main')).toBeVisible()

    const problems = []
    let stops = 0
    for (let i = 0; i < 120; i++) {
      await page.keyboard.press('Tab')
      const result = await page.evaluate(() => {
        const el = document.activeElement
        if (!el || el === document.body) return null
        const cs = getComputedStyle(el)
        const hasOutline = cs.outlineStyle !== 'none' && parseFloat(cs.outlineWidth) > 0
        const hasShadow = cs.boxShadow !== 'none'
        const rect = el.getBoundingClientRect()
        const cx = rect.left + rect.width / 2
        const cy = rect.top + rect.height / 2
        const hit = document.elementFromPoint(cx, cy)
        const notObscured = !!hit && (el === hit || el.contains(hit))
        const label = (el.getAttribute('aria-label') || el.textContent || el.tagName).trim().slice(0, 50)
        return { label, visibleFocus: hasOutline || hasShadow, notObscured }
      })
      if (result === null) break
      stops++
      if (!result.visibleFocus) problems.push(`no visible focus indicator: ${result.label}`)
      if (!result.notObscured) problems.push(`focus obscured: ${result.label}`)
    }

    expect(stops, 'expected to find several tab stops').toBeGreaterThanOrEqual(10)
    expect(problems).toEqual([])
  })
})

